rel_counts <- bind_rows(
  poverty_tested %>% count(reliability = reliability_2006_2010) %>% mutate(period = "2006–2010"),
  poverty_tested %>% count(reliability = reliability_2013_2017) %>% mutate(period = "2013–2017")
) %>%
  mutate(reliability = replace_na(reliability, "No data (NA)")) %>%
  pivot_wider(names_from = period, values_from = n, values_fill = 0) %>%
  mutate(reliability = factor(
    reliability,
    levels = c("Reliable", "Somewhat reliable", "Unreliable", "No data (NA)")
  )) %>%
  arrange(reliability)

rel_counts %>%
  gt() %>%
  cols_label(reliability = "Reliability class") %>%
